		const t = String.fromCharCode(bytes[pos + 4], bytes[pos + 5], bytes[pos + 6], bytes[pos + 7]);
		if (pos + 12 + n > bytes.length) throw new Error('truncated PNG chunk');
		const d = bytes.subarray(pos + 8, pos + 8 + n);
